(function(root){'use strict';
const VERSION='1.0.0';
const THEMES=[
{id:'economy',label:'Ekonomi och arbete',weight:20,metrics:['employment','income','poverty']},
{id:'safety',label:'Trygghet',weight:20,metrics:['unsafe']},
{id:'education',label:'Skola och omsorg',weight:20,metrics:['school','elderOutdoor']},
{id:'health',label:'Hälsa',weight:15,metrics:['health','life']},
{id:'housing',label:'Boende',weight:15,metrics:['crowding','housing']},
{id:'everyday',label:'Vardag och uppkoppling',weight:10,metrics:['broadband100']}];
const METRICS={
employment:{keys:['employment'],label:'Andel som arbetar',unit:'%',direction:1,high:'En stor andel arbetar.',low:'En mindre andel arbetar.'},
income:{keys:['income'],label:'Medianinkomst',unit:'kr/år',direction:1,high:'Den typiska inkomsten är hög.',low:'Den typiska inkomsten är låg.'},
poverty:{keys:['poverty'],label:'Låg ekonomisk standard',unit:'%',direction:-1,high:'Färre lever på låga inkomster.',low:'Fler lever på låga inkomster.'},
unsafe:{keys:['unsafe'],label:'Otrygghet på kvällen',unit:'%',direction:-1,high:'Färre känner sig otrygga på kvällen.',low:'Fler känner sig otrygga på kvällen.'},
school:{keys:['school'],label:'Behörighet till gymnasiet',unit:'%',direction:1,high:'Fler elever har betyg för att börja gymnasiet.',low:'Färre elever har betyg för att börja gymnasiet.'},
elderOutdoor:{keys:['elderOutdoor'],label:'Trivsel utomhus vid särskilt boende',unit:'%',direction:1,high:'Fler äldre trivs utomhus vid sitt boende.',low:'Färre äldre trivs utomhus vid sitt boende.'},
health:{keys:['health'],label:'Bra självskattad hälsa',unit:'%',direction:1,high:'Fler säger att de mår bra.',low:'Färre säger att de mår bra.'},
life:{keys:['lifeMale','lifeFemale'],label:'Medellivslängd, snitt av kvinnors och mäns mått',unit:'år',direction:1,high:'Den väntade livslängden är lång.',low:'Den väntade livslängden är kortare.'},
crowding:{keys:['crowding'],label:'Trångboddhet i flerbostadshus',unit:'%',direction:-1,high:'Färre bor trångt i flerbostadshus.',low:'Fler bor trångt i flerbostadshus.'},
housing:{keys:['housing'],label:'Nybyggda bostäder per tusen invånare',unit:'bostäder/1 000 inv.',direction:1,high:'Fler bostäder byggs i förhållande till folkmängden.',low:'Färre bostäder byggs i förhållande till folkmängden.'},
broadband100:{keys:['broadband100'],label:'Hushåll med snabbt bredband',unit:'%',direction:1,high:'Fler hushåll har snabbt bredband.',low:'Färre hushåll har snabbt bredband.'}};
const DEFAULT_WEIGHTS=Object.fromEntries(THEMES.map(t=>[t.id,t.weight]));
function weights(custom){const w=Object.fromEntries(THEMES.map(t=>[t.id,Math.min(100,Math.max(0,Number(custom?.[t.id]??t.weight)||0))]));const total=Object.values(w).reduce((a,b)=>a+b,0);return total?Object.fromEntries(THEMES.map(t=>[t.id,w[t.id]/total])):null;}
function observation(input,key,year,code){const ys=Object.keys(input.series[key]||{}).map(Number).filter(y=>y<=year).sort((a,b)=>b-a);const y=ys[0];if(y==null||year-y>input.maxAge)return null;const v=input.series[key][y]?.[code];return Number.isFinite(v)?{value:v,year:y,period:input.metadata[key]?.periods?.[y]||String(y)}:null;}
function metricObservation(input,id,year,code){const spec=METRICS[id],obs=spec.keys.map(k=>observation(input,k,year,code));if(obs.some(v=>v===null))return null;if(obs.some(v=>v.year!==obs[0].year||v.period!==obs[0].period))return null;return {value:obs.reduce((n,o)=>n+o.value,0)/obs.length,year:obs[0].year,period:obs[0].period};}
function percentilePoints(values,direction){const entries=Object.entries(values).filter(([,v])=>Number.isFinite(v)).sort((a,b)=>a[1]-b[1]);const result={};for(let i=0;i<entries.length;){let end=i;while(end+1<entries.length&&entries[end+1][1]===entries[i][1])end++;let p=entries.length>1?100*(i+end)/2/(entries.length-1):50;if(direction<0)p=100-p;for(let j=i;j<=end;j++)result[entries[j][0]]=p;i=end+1;}return result;}
function explain(row,w){if(!row.eligible)return 'Underlaget räcker inte för en rättvis placering. Se vilka uppgifter som saknas.';const entries=row.themes.filter(t=>w[t.id]>0&&t.score!=null).flatMap(t=>t.metrics.filter(m=>m.points!=null).map(m=>({m,impact:w[t.id]*(m.points-50)/t.metrics.filter(v=>v.points!=null).length})));const good=entries.filter(x=>x.m.points>=60).sort((a,b)=>b.impact-a.impact);const bad=entries.filter(x=>x.m.points<=40).sort((a,b)=>a.impact-b.impact);const parts=[];if(good[0])parts.push(METRICS[good[0].m.id].high+' Det höjer poängen.');if(bad[0])parts.push(METRICS[bad[0].m.id].low+' Det drar ner poängen.');if(!parts.length)parts.push('Resultaten ligger nära mitten av kommunerna i jämförelsen.');if(row.coverage<.999)parts.push('Vissa uppgifter saknas.');return parts.join(' ');}
function build(input,year,custom){year=Number(year);const w=weights(custom);if(!w)throw Error('Välj en vikt över noll för minst ett område.');const codes=Object.keys(input.municipalities),observations={},points={},counts={};const minPeers=Math.ceil(codes.length/2);for(const id of Object.keys(METRICS)){observations[id]={};for(const code of codes){const o=metricObservation(input,id,year,code);if(o)observations[id][code]=o;}counts[id]=Object.keys(observations[id]).length;points[id]=counts[id]>=minPeers?percentilePoints(Object.fromEntries(Object.entries(observations[id]).map(([k,v])=>[k,v.value])),METRICS[id].direction):{};}
const rows=codes.map(code=>{const themes=THEMES.map(t=>{const metrics=t.metrics.map(id=>({id,...(observations[id][code]||{}),points:points[id][code]??null,peers:counts[id]}));const valid=metrics.filter(m=>m.points!=null);return {id:t.id,label:t.label,score:valid.length?valid.reduce((s,m)=>s+m.points,0)/valid.length:null,coverage:valid.length/metrics.length,metrics};});const coverage=themes.reduce((s,t)=>s+w[t.id]*t.coverage,0);const eligible=coverage>=.8-1e-9&&themes.every(t=>w[t.id]===0||t.coverage>=.5);const valid=themes.filter(t=>w[t.id]>0&&t.score!=null);const availableWeight=valid.reduce((s,t)=>s+w[t.id],0);const score=eligible?Math.round(10*valid.reduce((s,t)=>s+w[t.id]*t.score,0)/availableWeight)/10:null;const row={code,name:input.municipalities[code].name,score,coverage,eligible,themes,rank:null};row.comment=explain(row,w);return row;});rows.sort((a,b)=>(b.eligible-a.eligible)||(b.score??-1)-(a.score??-1)||a.name.localeCompare(b.name,'sv'));let previousScore=null,previousRank=null;rows.forEach((r,i)=>{if(r.eligible){r.rank=r.score===previousScore?previousRank:i+1;previousScore=r.score;previousRank=r.rank;}});return {version:VERSION,year,weights:w,rows,ranked:rows.filter(r=>r.eligible).length,counts,minPeers};}
const API={VERSION,THEMES,METRICS,DEFAULT_WEIGHTS,weights,observation,metricObservation,percentilePoints,build};root.ScoreEngine=API;if(typeof module!=='undefined'&&module.exports)module.exports=API;
})(typeof window==='undefined'?globalThis:window);
